(() => { const map={"di bawah":["underneath","下方"],"di atas":["above","上方"],"di hadapan":["in front","前面"],"di luar":["outside","外面"],"Selepas itu":["After that","之后"],"Walaupun begitu":["Even so","即便如此"],"Sebaliknya":["On the contrary","相反"],"Kesimpulannya":["In conclusion","总之"],"Boleh saya pesan satu hidangan ini?":["May I order this dish?","我可以点这道菜吗？"],"Bagi cepat!":["Hurry up!","快一点！"],"Aku mahu itu sekarang!":["I want that now!","我现在就要那个！"],"Oi, ambil pesanan!":["Hey, take the order!","喂，来点餐！"],"Masuk melalui pintu utama.":["Enter through the main door.","从正门进入。"],"Belok selepas tiba.":["Turn after arriving.","到达后转弯。"],"Keluar dari bangunan.":["Leave the building.","离开建筑物。"],"Pulang ke rumah.":["Go home.","回家。"],"menulis":["to write","写"],"memtulis":["incorrect form","错误形式"],"mengtulis":["incorrect form","错误形式"],"penulisnya":["its author","它的作者"],"Masa, tempat dan keperluan peserta":["Time, place and participant requirements","时间、地点和参加者要求"],"Warna pakaian penceramah":["The speaker's clothing colour","演讲者衣服的颜色"],"Pendapat penulis tentang dewan":["The writer's opinion of the hall","作者对礼堂的看法"],"Cerita yang tidak dinyatakan":["An unstated story","未提及的故事"],"Namun":["However","然而"],"Selain itu":["Besides","此外"],"Seterusnya":["Next","接下来"],"Contohnya":["For example","例如"],"Ringkas dan menyatakan tujuan":["Concise and states the purpose","简洁并说明目的"],"Panjang tanpa fokus":["Long and unfocused","冗长且没有重点"],"Menggunakan singkatan tidak rasmi":["Uses informal abbreviations","使用非正式缩写"],"Tidak berkaitan dengan isi":["Unrelated to the content","与内容无关"],"Semak kaedah, tarikh dan sumber asal kedua-duanya":["Check both methods, dates and original sources","核查双方的方法、日期和原始来源"],"Pilih angka yang paling besar":["Choose the largest figure","选择最大的数字"],"Percaya sumber yang paling popular":["Trust the most popular source","相信最受欢迎的来源"],"Abaikan semua bukti":["Ignore all evidence","忽略所有证据"],"Hubungan itu mungkin dipengaruhi faktor lain":["The relationship may be influenced by other factors","这种关系可能受到其他因素影响"],"Semua korelasi ialah kebetulan":["All correlations are coincidences","所有相关性都是巧合"],"Data tidak pernah berguna":["Data is never useful","数据从来没有用"],"Sebab-akibat tidak boleh dikaji":["Cause and effect cannot be studied","因果关系无法研究"]}; for(const a of window.SWIFT_MALAY_DAILY_LEARNING.applications){ if(!a.id.endsWith("-02")) continue; for(const q of (a.questions||[])){ q.options=q.options.map(o=>{if(typeof o!=="string") return o; const pair=map[o]; if(!pair) throw new Error("Missing option translation: "+o); return {ms:o,en:pair[0],zh:pair[1]};}); }} })();

