(() => {
 const d=window.SWIFT_MALAY_DAILY_LEARNING;
 d.topics.push(...[{"id":"ms-topic-home-chores-03","topicId":"ms-topic-home-chores","difficulty":"beginner","title":"Tugas di rumah","titleEn":"Household chores","titleZh":"家务活动","body":"Pelajari kata kerja untuk tugas harian seperti menyapu, mengemas, membasuh dan menyiram. Gunakan kata kerja ini untuk menerangkan perkara yang dilakukan di rumah.","en":"Learn verbs for everyday chores such as sweeping, tidying, washing and watering. Use them to describe tasks done at home.","zh":"学习扫地、整理、洗涤和浇水等日常家务动词，并用这些动词描述家中进行的活动。","example":"Saya mengemas bilik setiap petang.","exampleEn":"I tidy my room every evening.","exampleZh":"我每天傍晚整理房间。"},{"id":"ms-topic-school-items-03","topicId":"ms-topic-school-items","difficulty":"beginner","title":"Barang di sekolah","titleEn":"School items","titleZh":"学校用品","body":"Kenali nama barang yang biasa digunakan di sekolah, seperti buku latihan, pemadam, pembaris dan beg. Gunakan kata ini dalam ayat mudah tentang pemilikan dan kegunaan.","en":"Learn the names of common school items, such as an exercise book, eraser, ruler and bag. Use them in simple sentences about possession and purpose.","zh":"学习练习簿、橡皮擦、尺和书包等常见学校用品名称，并用简单句表达所属关系和用途。","example":"Saya menyimpan pembaris di dalam bekas pensel.","exampleEn":"I keep my ruler in the pencil case.","exampleZh":"我把尺放在笔袋里。"},{"id":"ms-topic-weather-03","topicId":"ms-topic-weather","difficulty":"beginner","title":"Cuaca harian","titleEn":"Daily weather","titleZh":"日常天气","body":"Gunakan perkataan seperti panas, hujan, mendung dan berangin untuk menerangkan keadaan cuaca. Padankan penerangan dengan aktiviti yang sesuai.","en":"Use words such as hot, rainy, cloudy and windy to describe the weather. Match each description with a suitable activity.","zh":"使用炎热、下雨、多云和有风等词语描述天气，并根据天气选择合适的活动。","example":"Cuaca mendung sejak pagi tadi.","exampleEn":"It has been cloudy since this morning.","exampleZh":"从今天早上开始天气一直阴沉。"},{"id":"ms-topic-clothing-03","topicId":"ms-topic-clothing","difficulty":"beginner","title":"Pakaian dan kegunaannya","titleEn":"Clothing and its uses","titleZh":"衣物及其用途","body":"Kenali nama pakaian seperti baju, seluar, kasut dan jaket. Gunakan kata sifat mudah untuk menerangkan warna, saiz atau kesesuaian pakaian.","en":"Learn clothing words such as shirt, trousers, shoes and jacket. Use simple adjectives to describe colour, size or suitability.","zh":"学习上衣、裤子、鞋子和外套等衣物名称，并使用简单形容词描述颜色、尺寸或适合程度。","example":"Dia memakai jaket kerana cuaca sejuk.","exampleEn":"He wears a jacket because the weather is cold.","exampleZh":"他因为天气寒冷而穿上外套。"},{"id":"ms-topic-health-routine-03","topicId":"ms-topic-health-routine","difficulty":"beginner","title":"Rutin menjaga kesihatan","titleEn":"Healthy routines","titleZh":"健康习惯","body":"Bincangkan amalan mudah seperti minum air secukupnya, tidur teratur dan bersenam. Gunakan kata kerja harian untuk menerangkan tabiat yang baik.","en":"Discuss simple practices such as drinking enough water, sleeping regularly and exercising. Use everyday verbs to describe healthy habits.","zh":"讨论喝足够的水、规律睡眠和运动等简单做法，并使用日常动词描述良好习惯。","example":"Saya berjalan kaki selama dua puluh minit setiap hari.","exampleEn":"I walk for twenty minutes every day.","exampleZh":"我每天步行二十分钟。"},{"id":"ms-topic-public-places-03","topicId":"ms-topic-public-places","difficulty":"beginner","title":"Tempat awam","titleEn":"Public places","titleZh":"公共场所","body":"Kenali tempat awam seperti perpustakaan, klinik, balai polis dan pejabat pos. Gunakan kata sendi yang sesuai untuk menyatakan lokasi dan tujuan kunjungan.","en":"Learn public-place vocabulary such as library, clinic, police station and post office. Use suitable prepositions to state locations and reasons for visiting.","zh":"学习图书馆、诊所、警察局和邮局等公共场所词汇，并使用适当介词说明地点和到访目的。","example":"Kami meminjam buku di perpustakaan.","exampleEn":"We borrow books at the library.","exampleZh":"我们在图书馆借书。"},{"id":"ms-topic-measure-quantities-03","topicId":"ms-topic-measure-quantities","difficulty":"intermediate","title":"Ukuran dan kuantiti","titleEn":"Measurements and quantities","titleZh":"度量与数量","body":"Bezakan unit ukuran seperti meter, kilogram, liter dan minit. Pilih unit berdasarkan perkara yang diukur dan nyatakan kuantiti dengan tepat.","en":"Distinguish units such as metres, kilograms, litres and minutes. Choose a unit based on what is being measured and state quantities accurately.","zh":"区分米、千克、升和分钟等单位，根据测量对象选择单位，并准确表达数量。","example":"Bekas itu mengandungi dua liter air.","exampleEn":"The container holds two litres of water.","exampleZh":"容器里装有两升水。"},{"id":"ms-topic-comparatives-03","topicId":"ms-topic-comparatives","difficulty":"intermediate","title":"Perbandingan dan darjah","titleEn":"Comparison and degree","titleZh":"比较与程度","body":"Gunakan lebih, kurang, paling dan sama untuk membandingkan ciri. Pastikan perkara yang dibandingkan setara dan konteksnya jelas.","en":"Use lebih, kurang, paling and sama to compare qualities. Make sure the items being compared are comparable and the context is clear.","zh":"使用lebih、kurang、paling和sama比较特征，确保比较对象具有可比性且语境清楚。","example":"Laluan ini lebih pendek daripada laluan yang satu lagi.","exampleEn":"This route is shorter than the other route.","exampleZh":"这条路线比另一条路线短。"},{"id":"ms-topic-conditional-sentences-03","topicId":"ms-topic-conditional-sentences","difficulty":"intermediate","title":"Ayat bersyarat","titleEn":"Conditional sentences","titleZh":"条件句","body":"Perkataan jika dan sekiranya memperkenalkan syarat. Hubungkan syarat dengan hasil yang munasabah dan pastikan hubungan antara kedua-dua klausa jelas.","en":"Jika and sekiranya introduce conditions. Connect a condition to a reasonable outcome and make the relationship between the clauses clear.","zh":"Jika和sekiranya用于引出条件。将条件与合理结果连接，并确保两个分句之间的关系清楚。","example":"Jika hujan berterusan, perlawanan akan ditangguhkan.","exampleEn":"If the rain continues, the match will be postponed.","exampleZh":"如果持续下雨，比赛将会延期。"},{"id":"ms-topic-reported-speech-03","topicId":"ms-topic-reported-speech","difficulty":"intermediate","title":"Petikan dan penyataan semula","titleEn":"Quoting and paraphrasing","titleZh":"引用与转述","body":"Bezakan petikan langsung daripada penyataan semula. Kekalkan maksud asal, gunakan penanda petikan dengan betul dan nyatakan sumber apabila diperlukan.","en":"Distinguish direct quotations from paraphrases. Preserve the original meaning, use quotation markers correctly and identify the source when required.","zh":"区分直接引语与转述。保留原意，正确使用引述标记，并在需要时注明来源。","example":"Pengerusi menyatakan bahawa mesyuarat akan bermula pada pukul sepuluh.","exampleEn":"The chairperson stated that the meeting would begin at ten.","exampleZh":"主席表示会议将在十点开始。"},{"id":"ms-topic-paragraph-transitions-03","topicId":"ms-topic-paragraph-transitions","difficulty":"intermediate","title":"Peralihan antara perenggan","titleEn":"Transitions between paragraphs","titleZh":"段落之间的过渡","body":"Perenggan yang tersusun mempunyai hubungan idea yang jelas. Gunakan ayat penghubung untuk menunjukkan kesinambungan, peralihan atau perubahan fokus tanpa mengulang isi.","en":"Well-organised paragraphs have clear relationships between ideas. Use linking sentences to show continuity, transition or a change of focus without repeating points.","zh":"结构良好的段落具有清晰的观点联系。使用衔接句表达延续、过渡或重点转变，避免重复内容。","example":"Setelah membincangkan punca, perenggan seterusnya menghuraikan langkah penyelesaian.","exampleEn":"After discussing the causes, the next paragraph explains possible solutions.","exampleZh":"讨论原因后，下一段将说明可能的解决方案。"},{"id":"ms-topic-tone-and-register-03","topicId":"ms-topic-tone-and-register","difficulty":"advanced","title":"Nada dan laras bahasa","titleEn":"Tone and register","titleZh":"语气与语体","body":"Nilai hubungan antara penulis, pembaca dan tujuan komunikasi sebelum memilih laras. Laras rasmi, neutral dan santai mempunyai pilihan kata serta struktur yang berbeza.","en":"Consider the relationship between writer, reader and communicative purpose before choosing a register. Formal, neutral and casual registers use different vocabulary and structures.","zh":"选择语体前，应考虑作者、读者和沟通目的之间的关系。正式、中性和轻松语体在词汇与句式上各有不同。","example":"Laporan kepada pihak berkuasa menggunakan laras rasmi dan penyataan yang tepat.","exampleEn":"A report to an authority uses a formal register and precise statements.","exampleZh":"提交给主管机关的报告应采用正式语体和准确陈述。"},{"id":"ms-topic-evaluating-generalisation-03","topicId":"ms-topic-evaluating-generalisation","difficulty":"advanced","title":"Menilai generalisasi","titleEn":"Evaluating generalisations","titleZh":"评估概括性论断","body":"Kenal pasti dakwaan yang menggunakan perkataan seperti semua, sentiasa atau tidak pernah. Semak sama ada bukti mencukupi untuk menyokong skop dakwaan tersebut.","en":"Identify claims that use words such as all, always or never. Check whether the evidence is sufficient to support the scope of the claim.","zh":"识别使用“所有”“总是”或“从不”等词语的论断，并检查证据是否足以支持论断的范围。","example":"Satu contoh sahaja tidak mencukupi untuk membuktikan bahawa semua pengguna menghadapi masalah yang sama.","exampleEn":"A single example is not enough to prove that all users face the same problem.","exampleZh":"单一例子不足以证明所有用户都遇到相同问题。"},{"id":"ms-topic-synthesis-03","topicId":"ms-topic-synthesis","difficulty":"advanced","title":"Sintesis beberapa sumber","titleEn":"Synthesising multiple sources","titleZh":"综合多个来源","body":"Sintesis menggabungkan dapatan daripada beberapa sumber untuk membina pemahaman yang lebih menyeluruh. Kelompokkan persamaan, jelaskan perbezaan dan elakkan menyalin susunan sumber.","en":"Synthesis combines findings from several sources to build a more complete understanding. Group similarities, explain differences and avoid copying a source's structure.","zh":"综合是结合多个来源的发现，以建立更全面的理解。归纳相似之处、解释差异，并避免照搬来源的组织方式。","example":"Ketiga-tiga laporan menunjukkan trend yang sama, tetapi menggunakan kaedah pengukuran yang berbeza.","exampleEn":"All three reports show the same trend but use different measurement methods.","exampleZh":"三份报告都显示相同趋势，但采用了不同的测量方法。"},{"id":"ms-topic-counterargument-03","topicId":"ms-topic-counterargument","difficulty":"advanced","title":"Hujah balas dan sanggahan","titleEn":"Counterarguments and rebuttals","titleZh":"反方论点与反驳","body":"Hujah yang matang mengiktiraf pandangan berbeza dan menjawabnya dengan alasan atau bukti. Elakkan menggambarkan pandangan pihak lain secara tidak adil.","en":"A developed argument acknowledges opposing views and responds with reasons or evidence. Avoid misrepresenting another position.","zh":"成熟的论证会承认不同观点，并以理由或证据作出回应。避免不公平地歪曲他人立场。","example":"Walaupun kos awalnya tinggi, penjimatan jangka panjang menyokong pelaksanaan cadangan itu.","exampleEn":"Although the initial cost is high, long-term savings support the proposal.","exampleZh":"尽管初期成本较高，长期节省仍支持实施该建议。"},{"id":"ms-topic-data-interpretation-03","topicId":"ms-topic-data-interpretation","difficulty":"advanced","title":"Mentafsir data dan batasannya","titleEn":"Interpreting data and its limitations","titleZh":"解读数据及其局限","body":"Huraikan pola utama dalam jadual atau graf tanpa membuat dakwaan yang melampaui data. Nyatakan tempoh, saiz sampel dan batasan yang mempengaruhi tafsiran.","en":"Describe the main pattern in a table or graph without making claims beyond the data. State the period, sample size and limitations that affect interpretation.","zh":"描述表格或图表中的主要趋势，但不要作出超出数据范围的论断。说明会影响解读的时间范围、样本量和局限。","example":"Kadar meningkat dalam tempoh kajian, tetapi sampel yang kecil mengehadkan kesimpulan.","exampleEn":"The rate increased during the study period, but the small sample limits the conclusion.","exampleZh":"研究期间比率有所上升，但样本量较小，限制了结论的可靠性。"},{"id":"ms-topic-editing-ambiguity-03","topicId":"ms-topic-editing-ambiguity","difficulty":"advanced","title":"Menyunting ayat yang kabur","titleEn":"Editing ambiguous sentences","titleZh":"修改含糊句子","body":"Semak rujukan kata ganti, susunan frasa dan hubungan klausa. Tulis semula ayat apabila pembaca boleh mentafsirnya dengan lebih daripada satu cara.","en":"Check pronoun references, phrase order and clause relationships. Rewrite a sentence when readers could interpret it in more than one way.","zh":"检查代词指代、短语顺序和分句关系。当读者可能产生多种理解时，应改写句子以消除歧义。","example":"Pindahkan frasa masa ke kedudukan yang menjelaskan tindakan yang dimaksudkan.","exampleEn":"Move the time phrase to a position that clarifies the intended action.","exampleZh":"将时间短语移至能明确说明预期动作的位置。"},{"id":"ms-topic-policy-recommendations-03","topicId":"ms-topic-policy-recommendations","difficulty":"advanced","title":"Merangka cadangan berasaskan bukti","titleEn":"Developing evidence-based recommendations","titleZh":"制定有证据支持的建议","body":"Cadangan yang baik menghubungkan masalah, bukti, tindakan dan hasil yang boleh dinilai. Bezakan fakta daripada pertimbangan nilai dan nyatakan batas pelaksanaan.","en":"A sound recommendation links a problem, evidence, action and measurable outcome. Distinguish facts from value judgements and state implementation limits.","zh":"良好的建议应连接问题、证据、行动和可评估的结果。区分事实与价值判断，并说明实施限制。","example":"Cadangan itu menetapkan ukuran kejayaan dan tempoh penilaian yang jelas.","exampleEn":"The recommendation sets clear success measures and an evaluation period.","exampleZh":"该建议设定了明确的成功指标和评估期限。"}]);
 d.applications.push(...[{"id":"ms-application-plan-day-03","topicId":"ms-plan-day","difficulty":"beginner","title":"Susun jadual harian","titleEn":"Arrange a daily schedule","titleZh":"安排日常时间表","body":"Susun aktiviti mengikut urutan masa dan gunakan penanda waktu yang sesuai.","en":"Arrange activities in time order and use suitable time expressions.","zh":"按时间顺序安排活动，并使用恰当的时间表达。","example":"Susun aktiviti mengikut urutan masa dan gunakan penanda waktu yang sesuai.","exampleEn":"Arrange activities in time order and use suitable time expressions.","exampleZh":"按时间顺序安排活动，并使用恰当的时间表达。","questions":[{"q":{"ms":"Apakah urutan yang paling munasabah?","en":"What is the most logical order?","zh":"哪种顺序最合理？"},"options":[{"ms":"Bangun tidur, bersarapan, kemudian pergi ke sekolah.","en":"Wake up, have breakfast, then go to school.","zh":"起床、吃早餐，然后去学校。"},{"ms":"Pergi ke sekolah, tidur, kemudian bangun.","en":"Go to school, sleep, then wake up.","zh":"去学校、睡觉，然后起床。"},{"ms":"Bersarapan, tidur, kemudian mandi.","en":"Have breakfast, sleep, then bathe.","zh":"吃早餐、睡觉，然后洗澡。"},{"ms":"Tidur sepanjang hari sebelum bangun.","en":"Sleep all day before waking up.","zh":"醒来前睡一整天。"}],"answer":0}]},{"id":"ms-application-choose-clothing-03","topicId":"ms-choose-clothing","difficulty":"beginner","title":"Pilih pakaian yang sesuai","titleEn":"Choose suitable clothing","titleZh":"选择合适的衣物","body":"Padankan keadaan cuaca dengan pakaian yang sesuai dan berikan alasan ringkas.","en":"Match the weather with suitable clothing and give a brief reason.","zh":"根据天气选择合适的衣物，并简要说明理由。","example":"Padankan keadaan cuaca dengan pakaian yang sesuai dan berikan alasan ringkas.","exampleEn":"Match the weather with suitable clothing and give a brief reason.","exampleZh":"根据天气选择合适的衣物，并简要说明理由。","questions":[{"q":{"ms":"Cuaca hujan dan sejuk. Pakaian manakah paling sesuai?","en":"It is rainy and cold. Which clothing is most suitable?","zh":"天气寒冷又下雨。哪种衣物最合适？"},"options":[{"ms":"Jaket kalis air.","en":"A waterproof jacket.","zh":"防水外套。"},{"ms":"Baju renang.","en":"Swimwear.","zh":"泳衣。"},{"ms":"Selipar untuk pantai sahaja.","en":"Slippers for the beach only.","zh":"只适合海滩的拖鞋。"},{"ms":"Pakaian yang sangat nipis tanpa perlindungan.","en":"Very thin clothing without protection.","zh":"没有防护作用的薄衣服。"}],"answer":1}]},{"id":"ms-application-school-request-03","topicId":"ms-school-request","difficulty":"beginner","title":"Minta bantuan di sekolah","titleEn":"Ask for help at school","titleZh":"在学校请求帮助","body":"Gunakan ungkapan sopan untuk meminta bantuan daripada guru atau rakan.","en":"Use polite expressions to ask a teacher or classmate for help.","zh":"使用礼貌表达向老师或同学寻求帮助。","example":"Gunakan ungkapan sopan untuk meminta bantuan daripada guru atau rakan.","exampleEn":"Use polite expressions to ask a teacher or classmate for help.","exampleZh":"使用礼貌表达向老师或同学寻求帮助。","questions":[{"q":{"ms":"Pilih permintaan yang paling sopan kepada guru.","en":"Choose the most polite request to a teacher.","zh":"选择向老师提出的最礼貌请求。"},"options":[{"ms":"Cikgu, bolehkah cikgu terangkan soalan ini sekali lagi?","en":"Teacher, could you explain this question again?","zh":"老师，您可以再解释一次这道题吗？"},{"ms":"Terangkan sekarang!","en":"Explain it now!","zh":"现在就解释！"},{"ms":"Saya tidak peduli tentang soalan ini.","en":"I do not care about this question.","zh":"我不在乎这道题。"},{"ms":"Hei, buat kerja saya.","en":"Hey, do my work.","zh":"喂，帮我做作业。"}],"answer":0}]},{"id":"ms-application-public-service-03","topicId":"ms-public-service","difficulty":"beginner","title":"Dapatkan bantuan di tempat awam","titleEn":"Get help in a public place","titleZh":"在公共场所寻求帮助","body":"Kenal pasti tempat yang sesuai untuk mendapatkan perkhidmatan berdasarkan keperluan.","en":"Identify the appropriate place to obtain a service based on a need.","zh":"根据需求判断应前往哪个公共场所寻求服务。","example":"Kenal pasti tempat yang sesuai untuk mendapatkan perkhidmatan berdasarkan keperluan.","exampleEn":"Identify the appropriate place to obtain a service based on a need.","exampleZh":"根据需求判断应前往哪个公共场所寻求服务。","questions":[{"q":{"ms":"Anda mahu meminjam buku. Ke manakah anda patut pergi?","en":"You want to borrow a book. Where should you go?","zh":"你想借书，应该去哪里？"},"options":[{"ms":"Perpustakaan.","en":"Library.","zh":"图书馆。"},{"ms":"Balai polis.","en":"Police station.","zh":"警察局。"},{"ms":"Stesen minyak.","en":"Petrol station.","zh":"加油站。"},{"ms":"Kedai membaiki kereta.","en":"Car repair shop.","zh":"汽车维修店。"}],"answer":0}]},{"id":"ms-application-health-habit-03","topicId":"ms-health-habit","difficulty":"beginner","title":"Terangkan tabiat sihat","titleEn":"Describe a healthy habit","titleZh":"描述健康习惯","body":"Tulis satu ayat tentang tabiat sihat dengan kata kerja dan kekerapan yang jelas.","en":"Write one sentence about a healthy habit using a clear verb and frequency.","zh":"使用明确的动词和频率表达，写出一个健康习惯的句子。","example":"Tulis satu ayat tentang tabiat sihat dengan kata kerja dan kekerapan yang jelas.","exampleEn":"Write one sentence about a healthy habit using a clear verb and frequency.","exampleZh":"使用明确的动词和频率表达，写出一个健康习惯的句子。","questions":[{"q":{"ms":"Pilih ayat yang menyatakan tabiat sihat.","en":"Choose the sentence that describes a healthy habit.","zh":"选择描述健康习惯的句子。"},"options":[{"ms":"Saya bersenam tiga kali seminggu.","en":"I exercise three times a week.","zh":"我每周运动三次。"},{"ms":"Saya tidak pernah tidur dan sentiasa letih.","en":"I never sleep and am always tired.","zh":"我从不睡觉，而且总是很累。"},{"ms":"Saya minum air hanya apabila terlalu dahaga.","en":"I drink water only when extremely thirsty.","zh":"我只有在非常口渴时才喝水。"},{"ms":"Saya mengabaikan semua waktu rehat.","en":"I ignore all rest periods.","zh":"我忽略所有休息时间。"}],"answer":0}]},{"id":"ms-application-quantity-measure-03","topicId":"ms-quantity-measure","difficulty":"intermediate","title":"Pilih unit ukuran yang tepat","titleEn":"Choose the correct unit of measurement","titleZh":"选择正确的计量单位","body":"Pilih unit berdasarkan kuantiti yang hendak diukur dan elakkan kekeliruan antara jisim, isi padu dan panjang.","en":"Choose a unit based on the quantity being measured and avoid confusing mass, volume and length.","zh":"根据要测量的量选择单位，避免混淆质量、体积和长度。","example":"Pilih unit berdasarkan kuantiti yang hendak diukur dan elakkan kekeliruan antara jisim, isi padu dan panjang.","exampleEn":"Choose a unit based on the quantity being measured and avoid confusing mass, volume and length.","exampleZh":"根据要测量的量选择单位，避免混淆质量、体积和长度。","questions":[{"q":{"ms":"Unit manakah sesuai untuk menyatakan isi padu air dalam botol?","en":"Which unit is suitable for stating the volume of water in a bottle?","zh":"哪个单位适合表示瓶中水的体积？"},"options":[{"ms":"Kilogram.","en":"Kilogram.","zh":"千克。"},{"ms":"Liter.","en":"Litre.","zh":"升。"},{"ms":"Meter.","en":"Metre.","zh":"米。"},{"ms":"Jam.","en":"Hour.","zh":"小时。"}],"answer":1}]},{"id":"ms-application-comparison-03","topicId":"ms-comparison","difficulty":"intermediate","title":"Bandingkan dua pilihan","titleEn":"Compare two options","titleZh":"比较两个选项","body":"Bina perbandingan yang jelas dengan menggunakan lebih, kurang atau paling.","en":"Build a clear comparison using lebih, kurang or paling.","zh":"使用lebih、kurang或paling构成清晰的比较句。","example":"Bina perbandingan yang jelas dengan menggunakan lebih, kurang atau paling.","exampleEn":"Build a clear comparison using lebih, kurang or paling.","exampleZh":"使用lebih、kurang或paling构成清晰的比较句。","questions":[{"q":{"ms":"Ayat manakah membandingkan dua laluan dengan betul?","en":"Which sentence correctly compares two routes?","zh":"哪句话正确比较了两条路线？"},"options":[{"ms":"Laluan A lebih pendek daripada Laluan B.","en":"Route A is shorter than Route B.","zh":"路线A比路线B短。"},{"ms":"Laluan A paling daripada Laluan B.","en":"Route A most than Route B.","zh":"路线A最比路线B。"},{"ms":"Laluan A sama pendek lebih Laluan B.","en":"Route A same short more Route B.","zh":"路线A同样短更多路线B。"},{"ms":"Laluan A pendek kerana Laluan B.","en":"Route A short because Route B.","zh":"路线A短因为路线B。"}],"answer":0}]},{"id":"ms-application-condition-03","topicId":"ms-condition","difficulty":"intermediate","title":"Lengkapkan ayat bersyarat","titleEn":"Complete a conditional sentence","titleZh":"完成条件句","body":"Padankan klausa syarat dengan hasil yang munasabah menggunakan jika atau sekiranya.","en":"Match a condition clause with a reasonable result using jika or sekiranya.","zh":"使用jika或sekiranya，将条件分句与合理结果连接。","example":"Padankan klausa syarat dengan hasil yang munasabah menggunakan jika atau sekiranya.","exampleEn":"Match a condition clause with a reasonable result using jika or sekiranya.","exampleZh":"使用jika或sekiranya，将条件分句与合理结果连接。","questions":[{"q":{"ms":"Lengkapkan: Jika bekalan elektrik terputus, ...","en":"Complete: If the electricity supply is interrupted, ...","zh":"补全：如果电力供应中断，……"},"options":[{"ms":"aktiviti itu mungkin dihentikan sementara.","en":"the activity may be paused temporarily.","zh":"该活动可能会暂时停止。"},{"ms":"semua lampu akan menyala secara automatik tanpa bekalan.","en":"all lights will turn on automatically without power.","zh":"没有电源时所有灯都会自动亮起。"},{"ms":"bekalan elektrik tidak lagi diperlukan untuk semua alat.","en":"electricity will no longer be needed for any device.","zh":"所有设备都不再需要电力。"},{"ms":"keadaan itu pasti tidak memberi sebarang kesan.","en":"the situation will certainly have no effect.","zh":"这种情况肯定不会产生任何影响。"}],"answer":0}]},{"id":"ms-application-paraphrase-03","topicId":"ms-paraphrase","difficulty":"intermediate","title":"Tulis semula tanpa mengubah maksud","titleEn":"Paraphrase without changing the meaning","titleZh":"在不改变原意的情况下改写","body":"Tulis semula maklumat menggunakan struktur sendiri sambil mengekalkan maksud asal dan mengelakkan penyalinan.","en":"Rewrite information using your own structure while preserving the original meaning and avoiding copying.","zh":"用自己的句式改写信息，同时保留原意并避免照抄。","example":"Tulis semula maklumat menggunakan struktur sendiri sambil mengekalkan maksud asal dan mengelakkan penyalinan.","exampleEn":"Rewrite information using your own structure while preserving the original meaning and avoiding copying.","exampleZh":"用自己的句式改写信息，同时保留原意并避免照抄。","questions":[{"q":{"ms":"Apakah syarat utama penyataan semula yang baik?","en":"What is the main requirement of a good paraphrase?","zh":"良好转述的主要要求是什么？"},"options":[{"ms":"Maksud asal dikekalkan dengan ungkapan sendiri.","en":"The original meaning is preserved in one's own wording.","zh":"用自己的表达保留原意。"},{"ms":"Semua perkataan asal disalin tanpa perubahan.","en":"All original words are copied unchanged.","zh":"原文所有词语都原样照抄。"},{"ms":"Maklumat penting dibuang supaya ayat lebih pendek.","en":"Important information is removed to shorten the sentence.","zh":"删去重要信息以缩短句子。"},{"ms":"Pendapat baharu ditambah walaupun tiada dalam sumber.","en":"A new opinion is added even though it is absent from the source.","zh":"即使来源中没有，也加入新的观点。"}],"answer":0}]},{"id":"ms-application-transition-03","topicId":"ms-transition","difficulty":"intermediate","title":"Baiki peralihan perenggan","titleEn":"Improve paragraph transitions","titleZh":"改善段落过渡","body":"Pilih ayat penghubung yang menunjukkan hubungan logik antara perenggan.","en":"Choose a linking sentence that shows a logical relationship between paragraphs.","zh":"选择能体现段落之间逻辑关系的衔接句。","example":"Pilih ayat penghubung yang menunjukkan hubungan logik antara perenggan.","exampleEn":"Choose a linking sentence that shows a logical relationship between paragraphs.","exampleZh":"选择能体现段落之间逻辑关系的衔接句。","questions":[{"q":{"ms":"Selepas menghuraikan masalah kesesakan, ayat manakah sesuai untuk memulakan perenggan penyelesaian?","en":"After explaining traffic congestion, which sentence is suitable to begin a solutions paragraph?","zh":"说明交通拥堵问题后，哪句话适合用来开启解决方案段落？"},"options":[{"ms":"Bagi menangani masalah tersebut, beberapa langkah boleh dilaksanakan.","en":"To address the problem, several measures can be implemented.","zh":"为了解决这个问题，可以采取几项措施。"},{"ms":"Saya suka warna biru.","en":"I like the colour blue.","zh":"我喜欢蓝色。"},{"ms":"Masalah itu tidak pernah disebut lagi tanpa sebab.","en":"That problem is never mentioned again without reason.","zh":"没有原因地再也不提那个问题。"},{"ms":"Perenggan ini tidak berkaitan dengan perbincangan.","en":"This paragraph is unrelated to the discussion.","zh":"本段与讨论无关。"}],"answer":0}]},{"id":"ms-application-register-rewrite-03","topicId":"ms-register-rewrite","difficulty":"advanced","title":"Sesuaikan laras untuk penerima","titleEn":"Adapt register for the audience","titleZh":"根据受众调整语体","body":"Tulis semula mesej santai dalam laras rasmi tanpa mengubah tujuan komunikasinya.","en":"Rewrite a casual message in a formal register without changing its communicative purpose.","zh":"将轻松语气的信息改写为正式语体，同时不改变沟通目的。","example":"Tulis semula mesej santai dalam laras rasmi tanpa mengubah tujuan komunikasinya.","exampleEn":"Rewrite a casual message in a formal register without changing its communicative purpose.","exampleZh":"将轻松语气的信息改写为正式语体，同时不改变沟通目的。","questions":[{"q":{"ms":"Pilih ayat yang sesuai untuk surat rasmi.","en":"Choose the sentence suitable for a formal letter.","zh":"选择适合正式信函的句子。"},"options":[{"ms":"Saya ingin memohon pertimbangan pihak tuan/puan berhubung perkara tersebut.","en":"I would like to request your consideration regarding the matter.","zh":"谨请贵方考虑此事。"},{"ms":"Korang kena settle benda ni cepat.","en":"You guys need to sort this out quickly.","zh":"你们得赶快把这件事搞定。"},{"ms":"Cepatlah jawab, saya tunggu.","en":"Reply quickly, I'm waiting.","zh":"快点回复，我在等。"},{"ms":"Benda tu memang teruk gila.","en":"That thing is really awful.","zh":"那件事真的糟透了。"}],"answer":0}]},{"id":"ms-application-generalisation-check-03","topicId":"ms-generalisation-check","difficulty":"advanced","title":"Semak dakwaan umum","titleEn":"Check a general claim","titleZh":"检查概括性论断","body":"Nilai sama ada bukti yang terhad menyokong dakwaan yang menggunakan kata seperti semua atau sentiasa.","en":"Assess whether limited evidence supports a claim using words such as all or always.","zh":"评估有限证据是否足以支持使用“所有”或“总是”等词语的论断。","example":"Nilai sama ada bukti yang terhad menyokong dakwaan yang menggunakan kata seperti semua atau sentiasa.","exampleEn":"Assess whether limited evidence supports a claim using words such as all or always.","exampleZh":"评估有限证据是否足以支持使用“所有”或“总是”等词语的论断。","questions":[{"q":{"ms":"Satu responden memberikan maklum balas negatif. Apakah kesimpulan paling wajar?","en":"One respondent gave negative feedback. What is the most reasonable conclusion?","zh":"一名受访者给出了负面反馈。哪项结论最合理？"},"options":[{"ms":"Seorang responden memberikan maklum balas negatif; dapatan ini belum mewakili semua pengguna.","en":"One respondent gave negative feedback; this finding does not yet represent all users.","zh":"一名受访者给出负面反馈；这一发现尚不能代表所有用户。"},{"ms":"Semua pengguna tidak berpuas hati.","en":"All users are dissatisfied.","zh":"所有用户都不满意。"},{"ms":"Tiada pengguna lain mempunyai pandangan berbeza.","en":"No other user has a different view.","zh":"其他用户都没有不同看法。"},{"ms":"Maklum balas itu membuktikan punca masalah sepenuhnya.","en":"The feedback proves the entire cause of the problem.","zh":"该反馈完全证明了问题的原因。"}],"answer":0}]},{"id":"ms-application-source-synthesis-03","topicId":"ms-source-synthesis","difficulty":"advanced","title":"Gabungkan dapatan sumber","titleEn":"Synthesize findings from sources","titleZh":"综合不同来源的发现","body":"Gabungkan maklumat daripada beberapa sumber dengan mengenal pasti persamaan, perbezaan dan batas setiap sumber.","en":"Combine information from several sources by identifying similarities, differences and each source's limitations.","zh":"通过识别相似点、差异和各来源的局限，综合多个来源的信息。","example":"Gabungkan maklumat daripada beberapa sumber dengan mengenal pasti persamaan, perbezaan dan batas setiap sumber.","exampleEn":"Combine information from several sources by identifying similarities, differences and each source's limitations.","exampleZh":"通过识别相似点、差异和各来源的局限，综合多个来源的信息。","questions":[{"q":{"ms":"Apakah pendekatan terbaik apabila dua laporan menggunakan kaedah berbeza?","en":"What is the best approach when two reports use different methods?","zh":"两份报告采用不同方法时，最佳做法是什么？"},"options":[{"ms":"Bandingkan kaedah dan konteks sebelum mensintesiskan dapatan.","en":"Compare methods and contexts before synthesising the findings.","zh":"综合研究结果前，先比较方法和背景。"},{"ms":"Gabungkan semua angka tanpa menyemak kaedah.","en":"Combine all figures without checking the methods.","zh":"不检查方法就合并所有数字。"},{"ms":"Pilih laporan yang paling panjang sahaja.","en":"Choose only the longest report.","zh":"只选择篇幅最长的报告。"},{"ms":"Abaikan perbezaan supaya kesimpulan kelihatan seragam.","en":"Ignore differences so the conclusion appears uniform.","zh":"忽略差异，让结论看起来一致。"}],"answer":0}]},{"id":"ms-application-counterargument-response-03","topicId":"ms-counterargument-response","difficulty":"advanced","title":"Jawab hujah balas secara adil","titleEn":"Respond fairly to a counterargument","titleZh":"公平回应反方论点","body":"Kenal pasti inti hujah balas dan jawab dengan alasan atau bukti yang berkaitan, bukan dengan menyerang pihak yang mengemukakannya.","en":"Identify the core counterargument and respond with relevant reasons or evidence rather than attacking the person who raised it.","zh":"找出反方论点的核心，并以相关理由或证据回应，而不是攻击提出观点的人。","example":"Kenal pasti inti hujah balas dan jawab dengan alasan atau bukti yang berkaitan, bukan dengan menyerang pihak yang mengemukakannya.","exampleEn":"Identify the core counterargument and respond with relevant reasons or evidence rather than attacking the person who raised it.","exampleZh":"找出反方论点的核心，并以相关理由或证据回应，而不是攻击提出观点的人。","questions":[{"q":{"ms":"Respons manakah paling kukuh terhadap hujah balas?","en":"Which response is the strongest to a counterargument?","zh":"哪种回应最有力地回应了反方论点？"},"options":[{"ms":"Akui kebimbangan tentang kos, kemudian bentangkan anggaran kos jangka panjang.","en":"Acknowledge the cost concern, then present a long-term cost estimate.","zh":"承认对成本的担忧，然后提出长期成本估算。"},{"ms":"Panggil pihak itu tidak bijak.","en":"Call the other side foolish.","zh":"称对方愚蠢。"},{"ms":"Ulang dakwaan asal tanpa bukti tambahan.","en":"Repeat the original claim without additional evidence.","zh":"不提供额外证据，只重复原来的论断。"},{"ms":"Tukar topik supaya hujah balas tidak perlu dijawab.","en":"Change the topic so the counterargument does not need to be answered.","zh":"转移话题，以避免回应反方论点。"}],"answer":0}]},{"id":"ms-application-data-limits-03","topicId":"ms-data-limits","difficulty":"advanced","title":"Huraikan batasan data","titleEn":"Explain data limitations","titleZh":"说明数据局限","body":"Tafsir dapatan dengan mengambil kira saiz sampel, tempoh kajian dan kaedah pengumpulan data.","en":"Interpret findings while considering sample size, study period and data-collection methods.","zh":"解读研究结果时，应考虑样本量、研究期间和数据收集方法。","example":"Tafsir dapatan dengan mengambil kira saiz sampel, tempoh kajian dan kaedah pengumpulan data.","exampleEn":"Interpret findings while considering sample size, study period and data-collection methods.","exampleZh":"解读研究结果时，应考虑样本量、研究期间和数据收集方法。","questions":[{"q":{"ms":"Kajian melibatkan 12 peserta sahaja. Apakah batasan yang patut dinyatakan?","en":"The study involved only 12 participants. What limitation should be stated?","zh":"研究只涉及12名参与者。应说明哪项局限？"},"options":[{"ms":"Saiz sampel yang kecil mengehadkan kebolehumuman dapatan.","en":"The small sample size limits how widely the findings can be generalised.","zh":"样本量较小，限制了研究结果的普遍适用性。"},{"ms":"Dapatan itu semestinya mewakili seluruh negara.","en":"The findings must represent the entire country.","zh":"研究结果必然代表整个国家。"},{"ms":"Bilangan peserta tidak mempengaruhi tafsiran.","en":"The number of participants does not affect interpretation.","zh":"参与者人数不会影响解读。"},{"ms":"Kajian itu membuktikan semua sebab dan akibat.","en":"The study proves every cause and effect.","zh":"该研究证明了所有因果关系。"}],"answer":0}]},{"id":"ms-application-ambiguous-edit-03","topicId":"ms-ambiguous-edit","difficulty":"advanced","title":"Sunting ayat yang mempunyai dua tafsiran","titleEn":"Edit a sentence with two interpretations","titleZh":"修改存在两种解读的句子","body":"Kenal pasti bahagian yang menimbulkan kekaburan dan susun semula ayat supaya rujukan serta urutan tindakan jelas.","en":"Identify the part that creates ambiguity and restructure the sentence so references and action order are clear.","zh":"找出造成歧义的部分，并重新组织句子，使指代和动作顺序清楚。","example":"Kenal pasti bahagian yang menimbulkan kekaburan dan susun semula ayat supaya rujukan serta urutan tindakan jelas.","exampleEn":"Identify the part that creates ambiguity and restructure the sentence so references and action order are clear.","exampleZh":"找出造成歧义的部分，并重新组织句子，使指代和动作顺序清楚。","questions":[{"q":{"ms":"Apakah langkah pertama apabila ayat mempunyai rujukan kata ganti yang kabur?","en":"What is the first step when a sentence has an unclear pronoun reference?","zh":"句子中的代词指代不清时，第一步应做什么？"},"options":[{"ms":"Kenal pasti kata nama yang dimaksudkan dan tulis semula rujukannya dengan jelas.","en":"Identify the intended noun and rewrite the reference clearly.","zh":"找出所指的名词，并清楚改写指代。"},{"ms":"Tambah lebih banyak kata ganti tanpa penjelasan.","en":"Add more pronouns without clarification.","zh":"不作解释地增加更多代词。"},{"ms":"Padam semua kata nama dalam ayat.","en":"Delete all nouns in the sentence.","zh":"删除句子中的所有名词。"},{"ms":"Biarkan pembaca meneka maksudnya.","en":"Let readers guess the meaning.","zh":"让读者自行猜测意思。"}],"answer":0}]},{"id":"ms-application-recommendation-03","topicId":"ms-recommendation","difficulty":"advanced","title":"Bina cadangan yang boleh dinilai","titleEn":"Build an assessable recommendation","titleZh":"提出可评估的建议","body":"Hubungkan cadangan dengan masalah, bukti, pihak bertanggungjawab dan ukuran kejayaan yang boleh diperiksa.","en":"Link a recommendation to the problem, evidence, responsible party and measurable success criteria.","zh":"将建议与问题、证据、责任方及可核查的成功指标联系起来。","example":"Hubungkan cadangan dengan masalah, bukti, pihak bertanggungjawab dan ukuran kejayaan yang boleh diperiksa.","exampleEn":"Link a recommendation to the problem, evidence, responsible party and measurable success criteria.","exampleZh":"将建议与问题、证据、责任方及可核查的成功指标联系起来。","questions":[{"q":{"ms":"Komponen manakah menjadikan cadangan lebih mudah dinilai?","en":"Which component makes a recommendation easier to evaluate?","zh":"哪项内容能让建议更容易评估？"},"options":[{"ms":"Ukuran kejayaan dan tempoh penilaian yang jelas.","en":"Clear success measures and an evaluation period.","zh":"明确的成功指标和评估期限。"},{"ms":"Janji umum tanpa ukuran.","en":"A general promise without measures.","zh":"没有衡量标准的笼统承诺。"},{"ms":"Pendapat peribadi tanpa kaitan dengan masalah.","en":"A personal opinion unrelated to the problem.","zh":"与问题无关的个人意见。"},{"ms":"Senarai tindakan tanpa pihak yang bertanggungjawab.","en":"A list of actions without responsible parties.","zh":"没有责任方的行动清单。"}],"answer":0}]}]);
 d.contentVersion="u3-ms-daily-0.3.0";
})();

/* Keep each new Application linked to its corresponding authored Topic. */
(() => {
 const d=window.SWIFT_MALAY_DAILY_LEARNING;
 const links={
  "plan-day":"time-duration","choose-clothing":"clothing","school-request":"school-items",
  "public-service":"public-places","health-habit":"health-routine","quantity-measure":"measure-quantities",
  "comparison":"comparatives","condition":"conditional-sentences","paraphrase":"reported-speech",
  "transition":"paragraph-transitions","register-rewrite":"tone-and-register",
  "generalisation-check":"evaluating-generalisation","source-synthesis":"synthesis",
  "counterargument-response":"counterargument","data-limits":"data-interpretation",
  "ambiguous-edit":"editing-ambiguity","recommendation":"policy-recommendations"
 };
 for(const a of d.applications){
  if(!a.id.endsWith("-03")) continue;
  const key=a.id.replace(/^ms-application-/,"").replace(/-03$/,"");
  if(links[key]) a.topicId="ms-topic-"+links[key];
 }
})();

